55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	  moonstone: 25,
66	};
67	
68	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
69	
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const sumOfItemBasePremiums = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
75	
76	const itemsGroupedByType = (items: Item[]): Item[][] => {
77	  const byType = new Map<string, Item[]>();
78	  for (const item of items) {
79	    byType.set(item.type, [...(byType.get(item.type) ?? []), item]);
80	  }
81	  return [...byType.values()];
82	};
83	
84	const formsBlock = (sameTypeItems: Item[]): boolean => sameTypeItems.length === BLOCK_SIZE;
85	
86	const sameTypeBasePremium = (sameTypeItems: Item[]): number =>
87	  formsBlock(sameTypeItems) ? BLOCK_BASE_PREMIUM : sumOfItemBasePremiums(sameTypeItems);
88	
89	const policyBasePremium = (items: Item[]): number =>
90	  itemsGroupedByType(items).reduce(
91	    (sum, sameTypeItems) => sum + sameTypeBasePremium(sameTypeItems),
92	    0,
93	  );
94	
95	const withFirstInsuranceSurcharge = (policyBase: number): number =>
96	  policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
97	
98	const roundPremiumInMHPCOsFavor = Math.ceil;
99	
100	const CURSE_SURCHARGE = 0.5;
101	
102	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
103	const HIGH_ENCHANTMENT_THRESHOLD = 5;
104	
105	const isHighlyEnchanted = (item: Item): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
107	
108	const itemSurcharge = (item: Item): number => {
109	  const base = itemBasePremium(item);
110	  const curse = item.cursed === true ? base * CURSE_SURCHARGE : 0;
111	  const enchantment = isHighlyEnchanted(item) ? base * HIGH_ENCHANTMENT_SURCHARGE : 0;
112	  return curse + enchantment;
113	};
114	
115	const totalItemSurcharges = (items: Item[]): number =>
116	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
117	
118	const premiumBeforeFee = (items: Item[]): number =>
119	  withFirstInsuranceSurcharge(policyBasePremium(items)) + totalItemSurcharges(items);
120	
121	const quotePremium = (items: Item[]): number =>
122	  roundPremiumInMHPCOsFavor(premiumBeforeFee(items) + PROCESSING_FEE);
123	
124	const runStep = (step: Step): StepResult => {
125	  if (step.op === "quote") {
126	    return { premium: quotePremium(step.items) };
127	  }
128	  throw new Error(`Unsupported step: ${step.op}`);
129	};
130	
131	export const runScenario = (scenario: Scenario): ScenarioResult => ({
132	  results: scenario.steps.map(runStep),
133	});
